struct Command{std::string op,word;long long a=0,b=0;};
int main(){
 std::ifstream input("data/records.txt");if(!input){std::cout<<"open-failed\n";return 0;}
 std::vector<Record>records;if(!load_records(input,records)){std::cout<<"invalid-data\n";return 0;}
 std::vector<Command>commands;
 while(true){std::cin>>std::ws;if(std::cin.eof())break;Command c;if(commands.size()>=32||!(std::cin>>c.op)){std::cout<<"invalid\n";return 0;}
  if(c.op=="find"){if(!(std::cin>>c.a)||c.a<1||c.a>9999){std::cout<<"invalid\n";return 0;}}
  else if(c.op=="range"){if(!(std::cin>>c.a>>c.b)||c.a< -10000||c.b>10000||c.a>c.b){std::cout<<"invalid\n";return 0;}}
  else if(c.op=="freq"){if(!(std::cin>>c.word)||!valid_word(c.word)){std::cout<<"invalid\n";return 0;}}
  else if(c.op=="audit"){if(!(std::cin>>c.a)||c.a<0||c.a>4294967295LL){std::cout<<"invalid\n";return 0;}}
  else if(c.op!="list"){std::cout<<"invalid\n";return 0;}commands.push_back(c);
 }
 const auto byId=index_id(records),byValue=index_value(records);
 std::ofstream output("index-report.txt");if(!output){std::cout<<"io-error\n";return 0;}output<<make_report(records);output.close();if(!output){std::cout<<"io-error\n";return 0;}
 for(const Command&c:commands){
  if(c.op=="find")std::cout<<find_record(byId,static_cast<int>(c.a))<<'\n';
  else if(c.op=="range")std::cout<<"sum "<<range_sum(byValue,static_cast<int>(c.a),static_cast<int>(c.b))<<'\n';
  else if(c.op=="freq")std::cout<<"count "<<frequency(records,c.word)<<'\n';
  else if(c.op=="audit")std::cout<<(random_audit(static_cast<std::uint32_t>(c.a))?"rng ok":"rng failed")<<'\n';
  else{for(std::size_t i=0;i<byId.size();++i){if(i)std::cout<<' ';const Record&r=byId[i];std::cout<<r.id<<':'<<r.word<<':'<<r.value;}std::cout<<'\n';}
 }
}

