#include "domain.hpp"
#include <algorithm>
#include <set>
#include <map>
#include <numeric>
#include <random>
#include <sstream>
bool valid_word(const std::string&s){if(s.empty()||s.size()>12)return false;for(char c:s)if(c<'a'||c>'z')return false;return true;}
bool load_records(std::istream&in,std::vector<Record>&out){
 int n;if(!(in>>n)||n<0||n>64)return false;
 std::vector<Record>next;std::set<int>ids;
 for(int i=0;i<n;++i){Record r;if(!(in>>r.id>>r.word>>r.value)||r.id<1||r.id>9999||!valid_word(r.word)||r.value< -10000||r.value>10000||!ids.insert(r.id).second)return false;next.push_back(r);}
 in>>std::ws;if(!in.eof())return false;out=next;return true;
}
std::vector<Record> index_id(std::vector<Record>r){std::sort(r.begin(),r.end(),[](const Record&a,const Record&b){return a.id<b.id;});return r;}
static void merge_values(std::vector<Record>&r,std::size_t lo,std::size_t hi){
 if(hi-lo<2)return;auto mid=lo+(hi-lo)/2;merge_values(r,lo,mid);merge_values(r,mid,hi);
 std::vector<Record>tmp;auto i=lo,j=mid;
 while(i<mid&&j<hi){if(r[j].value<r[i].value)tmp.push_back(r[j++]);else tmp.push_back(r[i++]);}
 while(i<mid)tmp.push_back(r[i++]);while(j<hi)tmp.push_back(r[j++]);
 std::copy(tmp.begin(),tmp.end(),r.begin()+static_cast<std::ptrdiff_t>(lo));
}
std::vector<Record> index_value(std::vector<Record>r){merge_values(r,0,r.size());return r;}
std::string find_record(const std::vector<Record>&r,int id){auto p=std::lower_bound(r.begin(),r.end(),id,[](const Record&a,int id){return a.id<id;});if(p==r.end()||p->id!=id)return "missing";std::ostringstream out;out<<"found "<<p->id<<' '<<p->word<<' '<<p->value;return out.str();}
long long range_sum(const std::vector<Record>&r,int lo,int hi){auto first=std::lower_bound(r.begin(),r.end(),lo,[](const Record&a,int x){return a.value<x;});auto last=std::upper_bound(r.begin(),r.end(),hi,[](int x,const Record&a){return x<a.value;});return std::accumulate(first,last,0LL,[](long long sum,const Record&r){return sum+r.value;});}
int frequency(const std::vector<Record>&r,const std::string&word){std::map<std::string,int>counts;for(const Record&x:r)++counts[x.word];auto p=counts.find(word);return p==counts.end()?0:p->second;}
bool random_audit(std::uint32_t seed){std::mt19937 a(seed),b(seed);std::uniform_int_distribution<int>da(-10,10),db(-10,10);for(int i=0;i<16;++i){int x=da(a),y=db(b);if(x!=y||x< -10||x>10)return false;}return true;}

